from browser import Browser
import time,json
b=Browser();b.call('Page.navigate',{'url':'http://127.0.0.1:8000/?reference'});time.sleep(.5)
script='''(async()=>{const files=['Group 1063.svg',...Array.from({length:9},(_,i)=>`Frame ${55+i}.svg`)];const results=[];async function pixels(text){const im=new Image();im.src=URL.createObjectURL(new Blob([text],{type:'image/svg+xml'}));await im.decode();const c=document.createElement('canvas');c.width=1680;c.height=1079;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(im,0,0);URL.revokeObjectURL(im.src);return ctx.getImageData(0,0,1680,1079).data}for(let i=0;i<10;i++){const original=await(await fetch('assets/'+files[i])).text();const svg=document.querySelectorAll('.stage>svg')[i].cloneNode(true);if(i===0){};const a=await pixels(original),b=await pixels(new XMLSerializer().serializeToString(svg));let different=0;for(let k=0;k<a.length;k+=4)if(Math.max(Math.abs(a[k]-b[k]),Math.abs(a[k+1]-b[k+1]),Math.abs(a[k+2]-b[k+2]))>16)different++;results.push({screen:i+1,differentPixels:different,fraction:different/(1680*1079)})}return results})()'''
r=b.js(script);open('review/comparison.json','w').write(json.dumps(r,indent=2));print(r)
